TEST_CASE("drain_with_passthrough with HYBRID_FLAG_V: PB dumps v0 to scratch "
          "after the architectural counter reads (minimal prototype)")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;

  hybrid_state_v1 input{};
  input.magic   = HYBRID_STATE_MAGIC;
  input.version = HYBRID_STATE_VERSION;
  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_V;
  input.priv    = 3;
  input.vlenb   = 64;

  hybrid::StateDrain drain(bus, kScratch);
  (void) drain.drain_with_passthrough(input);

  // (a) the minimal sweep dumps v0 with a single vse8.v v0, (x7) via the PB.
  const uint32_t want = hybrid::encode_vse8_v(0, 7);
  std::optional<std::size_t> vse_idx;
  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
    const auto& op = bus.ops[i];
    if (op.kind == DmiOp::Kind::Write
        && op.reg >= hybrid::kProgbuf0
        && op.reg <= hybrid::kProgbuf0 + hybrid::kProgbufMaxInsns
        && op.value == want) { vse_idx = i; break; }
  }
  REQUIRE(vse_idx.has_value());

  // (b) the dump runs AFTER the mcycle/minstret reads, so its vse8.v (and any
  //     counter increments) cannot corrupt the drained counters. minstret
  //     (0xB02) is the last counter read before the sweep.
  std::optional<std::size_t> minstret_read_idx;
  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
    const auto& op = bus.ops[i];
    if (op.kind != DmiOp::Kind::Write || op.reg != RD::kCommand) continue;
    const auto regno   = static_cast<uint16_t>(op.value & 0xFFFFu);
    const bool is_read = ((op.value >> 16) & 1u) == 0u;
    if (is_read && regno == hybrid::regno_csr(0xB02)) minstret_read_idx = i;
  }
  REQUIRE(minstret_read_idx.has_value());
  CHECK(*minstret_read_idx < *vse_idx);
}

